/* Standalone English prototype; existing product CSS and navigation, synthetic local data only. */
const KEY='financebot-learning-path-existing-ui-en-v2';
const freshStudent=order=>({order:[...order],index:0,answers:[],phase:'main',choice:null,submitted:false,reviewIndex:0,reviewAnswers:[]});
const initial=()=>({analyzed:false,confirmed:false,extra:true,minN:2,generated:false,failed:false,approved:[],selectedReview:'diagnostic',published:false,rolledBack:false,seed:0,order:[0,1,2],student:freshStudent([0,1,2])});
let state;try{state={...initial(),...JSON.parse(localStorage.getItem(KEY)||'null')}}catch{state=initial()}
let busy=false,analysisStage=0,genStage=0,selectedNode='misconception',analyticsMode='first';
const app=document.getElementById('app');
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}};
const go=id=>location.hash=id;
const tag=(label,type='')=>`<span class="lp-label ${type?'lp-label--'+type:''}">${label}</span>`;
const btn=(text,action,primary=false,disabled=false)=>`<button class="btn ${primary?(['bank','publish','coverage','analytics'].includes(location.hash.slice(1))?'btn--instr-primary':'btn--primary'):'btn--ghost'}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const toast=text=>{const t=document.getElementById('toast');t.textContent=text;t.classList.add('is-visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('is-visible'),3200)};
const money=n=>n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const units=()=>['diagnostic','remediation',...(state.extra?['transfer']:[]),'parameters'];
const allApproved=()=>units().every(id=>state.approved.includes(id));
const ready=()=>state.confirmed&&state.generated&&!state.failed&&state.minN>=2&&allApproved();
const questions=[{id:'Q041',version:'v2',title:'Explain the value of NPV',skill:'S01 · Explain investment value',stem:'A project has a positive NPV. What does this tell us most directly?',options:['The project has no risk.','The project creates value at the required rate of return.','Every annual cash flow is positive.'],correct:1,explain:'Positive NPV means discounted cash inflows exceed the initial investment. It does not guarantee a risk-free project or positive cash flow every year.'},{id:'Q042',version:'v1',title:'Discount a one-year cash flow',skill:'S02 / S03 · Discount and subtract the investment',stem:'Invest $1,000 today and receive $1,320 in one year. At a 10% discount rate, what is the NPV?',options:['$200','$320','$1,200'],correct:0,explain:'Present value = $1,320 / 1.10 = $1,200. Subtract the $1,000 initial investment: NPV = $200.'},{id:'Q043',version:'v3',title:'Calculate a two-year NPV',skill:'S02 · Discount over multiple periods',stem:'Invest $12,000 today and receive one cash flow of $4,500 at the end of year 2. At a 20% discount rate, what is the NPV?',options:['−$8,875','−$8,250','−$7,500','−$5,520'],correct:0,explain:'Discount over both periods: $4,500 / 1.20² = $3,125. Subtract the initial investment: $3,125 − $12,000 = −$8,875.'}];
function navLink(label,glyph,target,current){return `<a class="nav__link ${current?'nav__link--active':''}" href="${target?'#'+target:'#'}" ${!target?'data-unavailable="true"':''} ${current?'aria-current="page"':''} aria-label="${label}" title="${!target?'Existing feature; outside this prototype':label}"><span class="nav__glyph ${/^\d$/.test(glyph)?'nav__glyph--step':''}" aria-hidden="true">${glyph}</span><span class="nav__text">${label}</span></a>`}
function shell(page){const student=page==='student';document.getElementById('shell').className=`app-shell app-shell--unified ${student?'app-shell--role app-shell--student':'app-shell--instructor'}${document.getElementById('shell').classList.contains('is-collapsed')?' is-collapsed':''}`;document.getElementById('sidebar').className='sidebar '+(student?'sidebar--student':'sidebar--instructor');document.getElementById('role-pill').textContent=student?'STUDENT PREVIEW':'INSTRUCTOR';document.getElementById('role-label').textContent=student?'Student Preview':'Instructor';document.getElementById('preview-label').hidden=!student;document.getElementById('share').hidden=student;document.getElementById('roles').open=false;const n=document.getElementById('nav');n.setAttribute('aria-label',student?'Student practice context':'Instructor');if(student){const s=state.student;n.innerHTML=navLink('Back to Course Home','←','bank',false)+`<div class="lp-progress-context"><h3>Capital Budgeting</h3><p>Topic Practice</p><ol>${s.order.map((qid,i)=>`<li class="${s.phase==='main'&&s.index===i?'is-current':''}">${questions[qid].title}${s.answers[i]!==undefined?' ✓':''}</li>`).join('')}</ol><hr class="lp-divider"><p>Main questions: ${s.answers.length} / 3</p><p>Review happens after the main questions.</p></div>`;return}
const groups=[['',[['My Courses','▦',null],['Canvas connection','↗',null],['Help & Tutorials','?',null]]],['Course workspace',[['Course Dashboard','⌂',null],['Course Materials','1',null],['Course Structure','2',null],['Generate Questions','3','overview'],['Review Queue','4','review'],['Question Bank','5','bank']]],['Explore & improve',[['Coverage Map','◇','coverage'],['Student Analytics','↗','analytics'],['Flags','!',null],['Import','⇧',null]]],['Course Settings',[['Exam Builder','▤',null],['Teaching Assistants','♙',null],['Settings','⚙',null],['Co-instructors','+',null]]]];const active=['overview','batch','graph','variants','generation'].includes(page)?'overview':page==='publish'?'bank':page;n.innerHTML=groups.map(([title,items])=>`<div class="nav__section">${title?`<p class="nav__group">${title}</p>`:''}${items.map(([label,glyph,target])=>navLink(label,glyph,target,target===active)).join('')}</div>`).join('')}
const generationHeader=page=>`<header class="gw-header"><div><h1>Generate questions</h1><p>Create focused questions from your course materials.</p></div><div class="gw-tabs" role="group" aria-label="Generation workspace views">${[['batch','Create a batch'],['overview','Learning path'],['generation','Generation activity']].map(([id,label])=>`<button data-route="${id}" aria-pressed="${id===page||(id==='overview'&&['graph','variants'].includes(page))}">${label}${id==='overview'?' · New':''}</button>`).join('')}</div></header>`;
const routeSteps=page=>`<nav class="gw-objectives" aria-label="Learning path steps"><div class="gw-pane-title">LEARNING PATH</div><div class="lp-step-list">${[['overview','Select main questions','Reuse approved versions'],['graph','Plan review branches','Confirm skills and evidence'],['variants','Configure variants','Check teaching constraints'],['generation','Generate drafts','Track each output']].map(([id,t,sub],i)=>`<a href="#${id}" ${page===id?'aria-current="step"':''}><b>${i+1}</b><span>${t}<small>${sub}</small></span></a>`).join('')}</div><div class="gw-pane-foot"><b>Capital Budgeting</b><br>3 approved main questions<br>LO 2 · Calculate and interpret NPV and IRR<hr class="lp-divider"><a class="gw-link" href="#bank">Edit main question order →</a><br><a class="gw-link" href="#coverage">View learning coverage →</a></div></nav>`;
const fact=(a,b)=>`<div class="gw-fact"><span>${a}</span><strong>${b}</strong></div>`;
const planSummary=()=>`<aside class="gw-plan"><h3>YOUR PLAN</h3><div class="gw-total">3 <small>existing main questions</small></div><p class="gw-plan-note">Keep the approved questions. Add focused review around them.</p>${fact('New question drafts',state.extra?'3':'2')}${fact('Parameter instances','12')}${fact('Approved originals changed','0')}<div class="gw-sources"><h3>SOURCE MATERIALS</h3><p>Lecture 3 · Capital Budgeting<small>Sample source · pp. 8–14</small></p><p>Q041 / v2 · Q042 / v1 · Q043 / v3<small>Pinned approved versions</small></p></div><div class="gw-sources"><h3>STUDENT EXPERIENCE</h3><p class="gw-plan-note">Main questions in order, then focused review. Only approved, published content is served.</p><a class="gw-link" href="#student">Preview as Student →</a></div></aside>`;
const footer=(text,buttons)=>`<footer class="gw-footer"><small>${text}</small><div class="lp-inline">${buttons}</div></footer>`;
function overview(){return `<section class="generation-workbench lp-workbench">${generationHeader('overview')}<div class="gw-grid">${routeSteps('overview')}<article class="gw-composer"><div class="gw-body"><p class="gw-eyebrow">BUILD FROM YOUR QUESTION BANK</p><h2>Extend approved questions</h2><p class="gw-lead">Use your existing questions as the main learning sequence. Review the suggested skills and branches before generating anything new.</p><span class="gw-selection">Capital Budgeting · 3 approved questions selected</span>${state.order.map((id,i)=>{const q=questions[id];return `<div class="lp-question-row"><div class="lp-inline"><span class="lp-number">${i+1}</span><div><strong>${q.title}</strong><span class="lp-muted">${q.id} · ${q.version} · ${q.skill}</span></div></div>${tag('Approved')}</div>`}).join('')}<div class="lp-note lp-section"><b>What happens next</b><br>Analysis proposes skills, possible misconceptions and missing review questions. It creates a draft plan, without rewriting or re-approving your original questions.</div><div class="lp-section"><h3 style="font-size:12px">The current generation workflow is still available</h3><p class="lp-muted">Use <a href="#batch">Create a batch</a> for ordinary questions from LOs. You can add those questions to a learning path after approving them.</p></div></div>${footer('Analysis does not generate or publish new questions.',btn(state.analyzed?'Continue to review branches →':'Analyze approved questions →',state.analyzed?'to-graph':'analyze',true,busy))}</article>${planSummary()}</div></section>`}
function batch(){return `<section class="generation-workbench lp-workbench">${generationHeader('batch')}<div class="gw-grid"><aside class="gw-objectives"><div class="gw-pane-title">LEARNING OBJECTIVES</div><div class="gw-objective-list"><h3 class="gw-topic">Capital Budgeting</h3>${['Explain the role of capital budgeting in maximizing firm value','Calculate and interpret NPV and IRR','Use NPV profiles and sensitivity analysis','Evaluate mutually exclusive projects using NPV','Apply payback period and profitability index rules'].map((t,i)=>`<label class="gw-objective ${i===1?'is-selected':''}"><input type="checkbox" ${i===1?'checked':''} disabled><span><strong>${t}</strong><small>Existing objective · reference view</small></span></label>`).join('')}</div><div class="gw-pane-foot">The existing batch generation flow stays available.</div></aside><article class="gw-composer"><div class="gw-body"><p class="gw-eyebrow">YOUR TEACHING BRIEF</p><h2>What should students practise?</h2><p class="gw-lead">Start with a few focused questions. We’ll use the materials assigned to each objective.</p><span class="gw-selection">1 objective selected · 3 questions each</span><label class="gw-label" for="brief">Instructions · optional</label><textarea id="brief" placeholder="e.g. Help students distinguish present value from net present value."></textarea><div class="lp-note lp-section">This reference tab preserves the current batch workflow. The new feature is under <b>Learning path</b>; it extends approved questions after instructor review.</div><div class="lp-section gw-settings"><div><label class="gw-label">Questions per objective</label><span class="lp-muted">3</span></div><div><label class="gw-label">Difficulty</label><span class="lp-muted">Balanced</span></div><div><label class="gw-label">Question type</label><span class="lp-muted">Multiple choice</span></div></div></div>${footer('Reference view · no generation request will be sent.',btn('Open learning path →','to-overview',true))}</article>${planSummary()}</div></section>`}
const nodeInfo={main:['Main question · Approved','Q043 · Two-year NPV','The existing approved version stays unchanged. Students encounter it in the main sequence before any targeted review.','Q043 / v3 · Lecture 3, p.14','Assesses S02 (discounting) and S03 (initial investment).'],skill:['Skill · Proposed','S02 · Discount over multiple periods','A reusable, assessable skill shared by multiple questions. Identify the cash-flow date, then discount to today.','Lecture 3 · pp.12–14 (sample reference)','Prerequisite: read a cash-flow timeline. Keep n ≥ 2 in this family.'],misconception:['Possible misconception','M02 · Discounting only once','Choosing −$8,250 is consistent with discounting once. It may also be a calculation slip. Use a diagnostic before deciding what support to offer.','Q043 / v3 · Option B; CF / (1 + r) − I','One answer is a signal, not a confirmed diagnosis.'],diagnostic:['Diagnostic question','D01 · Identify the time period','Ask how many periods separate a year-2 cash flow from today. This checks the concept without repeating the main answer.','S02 · Source timeline on pp.12–14','Correct → new-number check. Incorrect → guided review.'],remediation:['Guided review question','R01 · Discount in two steps','A prepared explanation and scaffold help the student work through each period. A hinted answer counts as supported practice.','S02 · Lecture 3, pp.12–14','Then offer a fresh parameter instance; do not recurse indefinitely.'],parameters:['Parameter variant pack','V01 · Same skill, new numbers','Change investment, cash flow and discount rate while preserving the structure, teaching goal and answer rules.','Q043 / v3 → F043 / template v1','Deploy 12 validated instances. n ≥ 2; distinct rounded answer options.'],transfer:['Optional transfer question','T01 · Apply the skill in a new context','Move from an equipment investment to a zero-coupon bond. New wording and context need their own content review.','S02 · New draft with source evidence','Optional advanced review; separate from the core three-step branch.']};
function node(id,title,sub){const approved=state.approved.includes(id),generated=state.generated&&units().includes(id);let label=id==='main'?'Approved':id==='skill'?'Skill':id==='misconception'?'Possible misconception':approved?'Approved':state.failed&&id==='transfer'?'Needs attention':generated?'Pending review':'Planned';return `<button class="lp-node ${!approved&&!['main','skill'].includes(id)?'lp-node--draft':''}" data-node="${id}" aria-pressed="${selectedNode===id}">${tag(label,id==='misconception'?'pending':approved||id==='main'?'':'neutral')}<strong>${title}</strong><small>${sub}</small></button>`}
function graph(){const n=nodeInfo[selectedNode];return `<section class="generation-workbench lp-workbench">${generationHeader('graph')}${busy&&analysisStage?`<div class="gw-notice" role="status">Analyzing: ${['reading pinned question versions','finding source evidence and skills','proposing branches and coverage gaps'][analysisStage-1]}…</div>`:''}<div class="gw-grid">${routeSteps('graph')}<article class="gw-composer"><div class="gw-body"><div class="lp-between"><div><p class="gw-eyebrow">REVIEW BRANCHES · Q043 / V3</p><h2>Review the proposed learning path</h2></div>${tag(state.confirmed?'Plan confirmed':'Needs confirmation',state.confirmed?'':'pending')}</div><p class="gw-lead">Select a node to inspect its purpose, evidence and routing rule. Students finish the main questions before entering this branch.</p>${!state.analyzed?'<div class="lp-note lp-note--warning" style="margin-bottom:14px">Illustrative proposal. Run analysis before confirming the plan.</div>':''}<div class="lp-graph"><div class="lp-graph-key"><span>LO 2 · Calculate and interpret NPV and IRR</span><span>Click a node for details</span></div><div class="lp-graph-row">${node('main','Two-year NPV','Existing approved question')}${node('skill','Discount over multiple periods','Shared skill · S02')}</div><div class="lp-arrow"><b>↓</b>Incorrect main answer · queue for later review</div>${node('misconception','Possibly discounted only once','Option B · −$8,250 is a clue, not a diagnosis')}<div class="lp-arrow"><b>↓</b>Check understanding first</div>${node('diagnostic','Identify the time period','How many periods from year 2 to today?')}<div class="lp-arrow"><b>↙</b>Needs support <span style="margin-left:24px">Understands the concept</span><b>↘</b></div><div class="lp-graph-row">${node('remediation','Discount in two steps','Prepared explanation + supported practice')}${node('parameters','Try different numbers','12 verified instances · same structure')}</div><div class="lp-arrow"><b>↓</b>After support: new-number check. Stop after at most 3 review answers.</div>${state.extra?node('transfer','Apply it in a new context','Optional extension · reviewed separately'):'<div class="lp-muted">Optional transfer question excluded from this batch.</div>'}</div></div>${footer(state.confirmed?'Plan confirmed. Configure and verify the parameter pack.':'Your original approved question remains unchanged.',`${!state.analyzed?btn('Analyze questions','analyze',false,busy):''}${btn(state.confirmed?'Configure variants →':'Confirm plan →','confirm',true,!state.analyzed||busy)}`)}</article><aside class="gw-plan lp-inspector"><h3>BRANCH DETAILS</h3>${tag(n[0],selectedNode==='misconception'?'pending':'blue')}<h2>${n[1]}</h2><p>${n[2]}</p><dl><dt>Source evidence</dt><dd>${n[3]}</dd><dt>Routing rule</dt><dd>${n[4]}</dd><dt>Review state</dt><dd>${state.approved.includes(selectedNode)?'This content version is approved.':state.generated&&units().includes(selectedNode)?'Draft generated; instructor review required.':selectedNode==='main'?'Original approval preserved.':'Proposed relationship; confirm before generation.'}</dd></dl><div class="gw-sources"><h3>GENERATION SCOPE</h3><label class="lp-muted lp-inline"><input id="extra" type="checkbox" ${state.extra?'checked':''} ${state.generated?'disabled':''}>Include the transfer question</label><p>${state.extra?3:2} new drafts + 12 parameter instances. Reuse 3 main questions.</p></div><div class="lp-note lp-note--warning lp-section">No approved branch available? Show the original explanation and keep the item for later review. Do not substitute an unrelated question.</div></aside></div></section>`}
const draws=[{I:12000,CF:4500,r:.2,n:2},{I:15000,CF:5000,r:.2,n:2},{I:9000,CF:6000,r:.1,n:3}];
function variants(){const d=draws[state.seed%3],vals=[d.CF/(1+d.r)**d.n-d.I,d.CF/(1+d.r)-d.I,d.CF-d.I,d.CF*(1+d.r)**d.n-d.I];return `<section class="generation-workbench lp-workbench">${generationHeader('variants')}<div class="gw-grid">${routeSteps('variants')}<article class="gw-composer"><div class="gw-body"><p class="gw-eyebrow">PARAMETER VARIANTS · F043 / V1</p><h2>Keep the skill. Change the numbers.</h2><p class="gw-lead">Review the template, allowed values and teaching constraints before approving an instance pack.</p><div class="lp-note">Invest <b>{I}</b> today and receive <b>{CF}</b> at the end of year <b>{n}</b>. At a discount rate of <b>{r}</b>, what is the NPV?</div><div class="lp-formula">NPV = CF / (1 + r)<sup>n</sup> − I</div><div class="lp-field-pair"><label class="lp-field">Initial investment · sample range<select><option>$9,000–$15,000</option></select></label><label class="lp-field">Discount rate · sample values<select><option>10% · 15% · 20%</option></select></label></div><div class="lp-field-pair"><label class="lp-field">Minimum periods · try 1<input id="minN" type="number" min="1" max="2" value="${state.minN}" ${state.published?'disabled':''}></label><label class="lp-field">Maximum periods<select><option>4 years</option></select></label></div><div class="lp-note ${state.minN<2?'lp-note--error':'lp-note--success'}">${state.minN<2?'<b>Validation failed.</b> With n = 1, the correct answer and “discount once” distractor collide. This also removes the multi-period learning goal.':'Teaching constraints pass: n ≥ 2, positive rates, distinct rounded options and a single correct answer.'}</div><table class="lp-table lp-section"><thead><tr><th>Option purpose</th><th>Computed rule</th></tr></thead><tbody><tr><td>Correct</td><td>CF / (1+r)<sup>n</sup> − I</td></tr><tr><td>Discount only once</td><td>CF / (1+r) − I</td></tr><tr><td>Do not discount</td><td>CF − I</td></tr><tr><td>Compound instead</td><td>CF × (1+r)<sup>n</sup> − I</td></tr></tbody></table><div class="lp-section"><div class="lp-between"><h3 style="font-size:13px">Sample ${state.seed%3+1} of 3</h3>${btn('Next sample ↻','seed')}</div><p class="gw-lead">Invest $${money(d.I)}; receive $${money(d.CF)} in year ${d.n}; rate ${d.r*100}%.</p>${vals.map((v,i)=>`<div class="gw-answer ${i===0?'is-correct':''}"><span>${'ABCD'[i]}</span><div>${v<0?'−':''}$${money(Math.abs(v))}${i===0?'<small>Computed correct answer</small>':''}</div></div>`).join('')}</div></div>${footer('Template or constraint changes require a fresh pack approval.',btn('Continue to generation →','to-generation',true))}</article><aside class="gw-plan"><h3>VALIDATION PLAN</h3><div class="gw-total">12 <small>fixed instances</small></div>${fact('Representative samples','3')}${fact('Original question edits','0')}${fact('Unique correct option',state.minN<2?'Failed':'Pass')}<div class="gw-sources"><h3>APPROVAL UNIT</h3><p class="gw-plan-note">Approve the template, constraints and exact instance set together. A new story or question structure requires separate content review.</p></div><div class="gw-sources"><h3>BEFORE PUBLICATION</h3><p class="gw-plan-note">Validate every deployed instance, including rounding and teaching constraints. Student sessions use these prepared questions.</p><a href="#graph" class="gw-link">Back to branch plan →</a></div></aside></div></section>`}
function generation(){return `<section class="generation-workbench lp-workbench">${generationHeader('generation')}<div class="gw-grid">${routeSteps('generation')}<article class="gw-composer"><div class="gw-body"><p class="gw-eyebrow">GENERATION ACTIVITY</p><h2>${state.generated?'Drafts ready for review':'Generate the confirmed plan'}</h2><p class="gw-lead">Each output is tracked separately. Completed drafts stay available when another branch needs attention.</p>${[['Existing main questions','Reuse pinned approved versions','3'],['New content drafts','Diagnostic, guided review'+(state.extra?' and transfer':''),state.extra?'3':'2'],['Parameter instances','F043 / v1 · fixed and verified','12']].map(([t,s,n])=>`<div class="lp-question-row"><div><strong>${t}</strong><span class="lp-muted">${s}</span></div><b>${n}</b></div>`).join('')}<div class="lp-note lp-section ${state.failed?'lp-note--warning':''}">${state.failed?'The transfer question could not be grounded in the selected source. Other drafts and approvals have been preserved.':state.generated?'Generated content is still a draft. Instructor approval and learning-path publication are separate steps.':state.confirmed?'The plan has been confirmed. Start generation when you are ready.':'Confirm the branch plan before starting generation.'}</div>${state.generated?`<table class="lp-table lp-section"><thead><tr><th>Output</th><th>Status</th></tr></thead><tbody>${units().map(id=>`<tr><td>${nodeInfo[id][1]}</td><td>${tag(state.failed&&id==='transfer'?'Needs source evidence':state.approved.includes(id)?'Approved':'Pending review',state.failed&&id==='transfer'?'error':state.approved.includes(id)?'':'pending')}</td></tr>`).join('')}</tbody></table>`:''}</div>${footer('Prototype simulation · no AI request or production write.',state.failed?btn('Retry failed branch only','retry-generation',true):state.generated?btn('Open review queue →','to-review',true):btn('Simulate partial failure','generate-failure',false,!state.confirmed||busy)+btn(busy?'Generating…':'Generate drafts →','generate',true,!state.confirmed||busy))}</article><aside class="gw-plan"><h3>RUN PROGRESS</h3>${[['Read pinned versions','Capture questions and source evidence.'],['Write each planned output','Keep stable output identifiers.'],['Validate answers and sources',state.failed?'Transfer question: insufficient source evidence.':'Check formulas, choices and constraints.'],['Save drafts for review','AI quality checks do not grant approval.']].map(([t,s],i)=>`<div class="lp-stage ${!state.generated&&genStage<=i?'is-pending':''} ${state.failed&&i===2?'is-error':''}"><strong>${i+1}. ${t}</strong><p>${s}</p></div>`).join('')}<p class="gw-plan-note lp-section">The production implementation will use the existing content-run and SSE infrastructure to restore task progress after navigation.</p></aside></div></section>`}
const reviews={diagnostic:{title:'D01 · Identify the time period',kind:'Diagnostic',stem:'How should a cash flow received at the end of year 2 be discounted to today?',options:['Discount it once.','Discount it over two periods.','Use the undiscounted amount.'],correct:1,exp:'The cash flow crosses two periods to reach today. At a constant rate, its present value is CF / (1+r)².'},remediation:{title:'R01 · Discount in two steps',kind:'Guided review',stem:'A $1,210 cash flow at the end of year 2 is worth $1,100 at the end of year 1, at 10%. What is it worth today?',options:['$1,000','$1,100','$1,210'],correct:0,exp:'Divide once more by 1.10: $1,100 / 1.10 = $1,000. A hinted response is supported practice, not independent verification.'},transfer:{title:'T01 · Apply the skill to a bond',kind:'Transfer',stem:'A zero-coupon bond pays $1,210 in two years. At a 10% required return, what is it worth today?',options:['$1,000','$1,100','$1,210'],correct:0,exp:'Discount the payment over both periods: $1,210 / 1.10² = $1,000. The changed context requires its own content approval.'},parameters:{title:'V01 · Parameter instance pack',kind:'Parameter pack'}};
const pageHead=(title,desc,actions='')=>`<header class="page-header"><div><h1 class="page-header__title">${title}</h1><p class="page-header__subtitle">${desc}</p></div><div class="lp-inline">${actions}</div></header>`;
function review(){if(!units().includes(state.selectedReview))state.selectedReview='diagnostic';const id=state.selectedReview,r=reviews[id];let body='';if(!state.generated)body=`<div class="lp-empty"><h2>No learning-path drafts yet</h2><p>Confirm the branch plan and generate drafts. Existing review-queue items are unaffected.</p>${btn('Open generation activity →','to-generation',true)}</div>`;else if(state.failed&&id==='transfer')body=`<div class="lp-empty"><h2>Source evidence needed</h2><p>Only this output failed. Supply evidence and retry; existing drafts and approvals remain.</p>${btn('Simulate source fix and retry','retry-generation',true)}</div>`;else if(id==='parameters')body=`<p class="gw-eyebrow">PARAMETER PACK / F043 · V1</p><h2>One template, a verified instance set</h2><div class="lp-formula">NPV = CF / (1 + r)<sup>n</sup> − I · n ≥ 2</div><div class="lp-note ${state.minN<2?'lp-note--error':'lp-note--success'}">${state.minN<2?'Validation failed. Fix the period constraint before approval.':'12 / 12 planned instances pass the simulated checks.'}</div><table class="lp-table lp-section"><tr><td>Review scope</td><td>Template + constraints + instance list</td></tr><tr><td>Representative samples</td><td>3, including boundary values</td></tr><tr><td>Content version</td><td>F043 / v1</td></tr><tr><td>Original question</td><td>Q043 / v3 · unchanged</td></tr></table><p class="lp-muted lp-section">Any change invalidates the pack approval. Published instances remain pinned to their original version.</p><a href="#variants" class="gw-link">Inspect template and sample answers →</a>`;else body=`<p class="gw-eyebrow">${r.kind.toUpperCase()} / DRAFT V1</p><h2>${r.title}</h2><div class="gw-stem">${r.stem}</div>${r.options.map((o,i)=>`<div class="gw-answer ${i===r.correct?'is-correct':''}"><span>${'ABC'[i]}</span><div>${o}${i===r.correct?'<small>Correct answer</small>':''}</div></div>`).join('')}<div class="gw-assessment"><h3>Explanation shown after submission</h3><p>${r.exp}</p></div><div class="lp-note lp-section">Sample evidence: Lecture 3, pp.12–14 → S02. Production review shows the source excerpt and exact version alongside AI-proposed relationships.</div>`;
return `<section class="generation-workbench lp-workbench"><header class="gw-header"><div><h1>Review queue</h1><p>Review generated content before students can access it.</p></div><div class="gw-tabs"><button data-action="existing-review">All questions</button><button aria-pressed="true">Learning path · ${state.approved.length}/${units().length}</button></div></header><div class="gw-grid"><aside class="gw-objectives"><div class="gw-pane-title">LEARNING-PATH DRAFTS</div><div class="gw-drafts lp-review-list">${units().map(key=>`<button data-review="${key}" aria-current="${key===id}"><strong>${reviews[key].title}</strong><small>${reviews[key].kind} · ${key==='parameters'?'12 instances':'1 question'}</small>${tag(state.failed&&key==='transfer'?'Needs attention':state.approved.includes(key)?'Approved':state.generated?'Pending review':'Not generated',state.approved.includes(key)?'':'pending')}</button>`).join('')}</div><div class="gw-pane-foot"><a href="#generation" class="gw-link">View generation activity →</a></div></aside><article class="gw-reader"><div class="gw-body">${body}</div>${footer(state.approved.includes(id)?'This version is approved. Publication is a separate action.':'Approve this content version, not the entire learning path.',btn(state.approved.includes(id)?'Approved':'Approve this item','approve',true,!state.generated||state.approved.includes(id)||(state.failed&&id==='transfer')||(id==='parameters'&&state.minN<2)))}</article><aside class="gw-plan lp-inspector"><h3>CONTENT DETAILS</h3>${fact('Learning objective','LO 2')}${fact('Primary skill','S02')}${fact('Origin','Q043 / v3')}${fact('Role',r.kind)}<div class="gw-sources"><h3>WHY THIS QUESTION?</h3><p>${nodeInfo[id][2]}</p></div><div class="gw-sources"><h3>READY TO PUBLISH?</h3><p>${state.approved.length} of ${units().length} review units approved.</p>${btn('Check publication →','to-publish',true)}</div></aside></div></section>`}
function bank(){return `<section class="lp-view">${pageHead('Question Bank','Manage your approved questions and their learning order.',btn('Preview as Student','to-student'))}<div class="filter-tabs"><button class="filter-tabs__tab" data-action="approved-bank">Approved questions</button><button class="filter-tabs__tab filter-tabs__tab--active">Learning sequence</button><button class="filter-tabs__tab" data-route="publish">Publication</button></div><div class="lp-two"><section class="lp-panel"><div class="lp-between"><h2>Capital Budgeting · Main questions</h2>${tag('3 approved')}</div><p class="lp-muted">Order belongs to this learning plan. Moving a question does not change its content or approval.</p>${state.order.map((id,i)=>`<div class="lp-question-row"><div class="lp-inline"><span class="lp-number">${i+1}</span><div><strong>${questions[id].title}</strong><span class="lp-muted">${questions[id].id} / ${questions[id].version} · ${questions[id].skill}</span></div></div><div class="lp-inline">${tag('Approved')}<button class="btn btn--ghost btn--sm" data-up="${i}" aria-label="Move ${questions[id].id} up" ${i===0||state.published?'disabled':''}>↑</button></div></div>`).join('')}<div class="lp-note lp-section">Review questions are outside the main sequence. Students complete these 3 main questions first, then review their mistakes together.</div></section><aside class="lp-panel"><h2>Learning-path status</h2>${fact('Main questions','3')}${fact('Branch plan',state.confirmed?'Confirmed':'Needs confirmation')}${fact('Approved review units',state.approved.length+' / '+units().length)}${fact('Publication',state.published?'Revision 1':'Draft')}<hr class="lp-divider"><p class="lp-muted">Existing questions and their previous attempts stay intact. Newly generated branches need their own approval.</p><div class="lp-inline lp-section">${btn('Edit review branches →','to-graph',true)}${btn('Check publication','to-publish')}</div></aside></div></section>`}
function publish(){const checks=[['Existing approved main versions are pinned',true],['Skills and routing confirmed by the instructor',state.confirmed],['New content and variant pack approved',ready()],['Parameter constraints pass',state.minN>=2],['Fallback and review limits are explicit',true],['Existing student sessions keep their version',true]];return `<section class="lp-view">${pageHead('Question Bank','Publish the reviewed learning sequence when it is ready.',btn('Preview as Student','to-student'))}<div class="filter-tabs"><button class="filter-tabs__tab" data-action="approved-bank">Approved questions</button><button class="filter-tabs__tab" data-route="bank">Learning sequence</button><button class="filter-tabs__tab filter-tabs__tab--active">Publication</button></div><div class="lp-two"><section class="lp-panel"><div class="lp-between"><h2>Compatibility check</h2>${tag('Read-only preview','blue')}</div><table class="lp-table"><thead><tr><th>Existing asset</th><th>What changes?</th></tr></thead><tbody><tr><td>Approved main questions</td><td>Reuse 3 pinned versions; no content edits</td></tr><tr><td>Prior attempts and Review Book</td><td>Preserve all records and question versions</td></tr><tr><td>Older questions without skill tags</td><td>Add proposed metadata separately</td></tr><tr><td>New branches and variants</td><td>Draft → approved → published, independently</td></tr><tr><td>Generation already in progress</td><td>Finishes using its original snapshot</td></tr></tbody></table><div class="lp-note lp-section">Publication applies to new Topic Practice sessions in Capital Budgeting. Existing sessions retain their pinned plan; emergency content withdrawal can still stop an unsafe question.</div><h2 class="lp-section">What a publication contains</h2><p class="lp-muted">Main sequence + confirmed skill graph + approved question versions + verified instance set + bounded review rules.</p><p class="lp-muted">A later edit creates a draft revision. It does not silently replace questions in an active session.</p></section><aside class="lp-panel"><div class="lp-between"><h2>Publication checklist</h2>${tag(`${checks.filter(x=>x[1]).length} / ${checks.length}`,ready()?'':'pending')}</div>${checks.map(([t,ok])=>`<div class="lp-question-row"><span class="lp-muted">${ok?'✓':'○'} ${t}</span></div>`).join('')}<p class="lp-muted lp-section">${state.published?'Revision 1 published in this demo.':state.rolledBack?'New sessions restored to the previous mode in this demo.':'Draft revision 1 · instructor action required.'}</p><div class="lp-inline lp-section">${btn(state.published?'Revision 1 published':'Publish revision 1','publish',true,!ready()||state.published)}${state.published?btn('Roll back new sessions','rollback'):btn('Open review queue','to-review')}</div></aside></div></section>`}
function coverage(){return `<section class="lp-view">${pageHead('Coverage Map','Find coverage gaps and trace questions back to their learning objectives.',btn('Build review branches →','to-graph',true))}<div class="filter-tabs"><button class="filter-tabs__tab" data-action="existing-coverage">Question coverage</button><button class="filter-tabs__tab filter-tabs__tab--active">Review coverage · New</button></div><div class="lp-panel"><div class="lp-between"><h2>Capital Budgeting</h2>${tag('Draft teaching map','pending')}</div><table class="lp-table"><thead><tr><th>Skill</th><th>Main question</th><th>Diagnostic</th><th>Guided review</th><th>Fresh check</th></tr></thead><tbody><tr><td>S01 · Explain investment value</td><td>Q041 / v2</td><td>${tag('Not planned','neutral')}</td><td>Original explanation</td><td>${tag('Gap','pending')}</td></tr><tr><td>S02 · Multi-period discounting</td><td>Q042 / v1, Q043 / v3</td><td>D01 · ${state.approved.includes('diagnostic')?'Approved':state.generated?'Draft':'Planned'}</td><td>R01 · ${state.approved.includes('remediation')?'Approved':state.generated?'Draft':'Planned'}</td><td>V01 · 12 instances</td></tr><tr><td>S03 · Subtract initial investment</td><td>Q042 / v1, Q043 / v3</td><td>${tag('Not planned','neutral')}</td><td>Original explanation</td><td>${tag('Gap','pending')}</td></tr></tbody></table><div class="lp-note lp-note--warning lp-section">A missing branch stays visible. In this example, S01 and S03 retain the original explanation and a review reminder until appropriate content is approved.</div></div><div class="lp-two lp-section"><section class="lp-panel"><h2>One skill can support several questions</h2><p class="lp-muted">Reuse stable skill IDs and reviewed support content. A failed multi-skill question does not prove that every linked skill is weak.</p></section><section class="lp-panel"><h2>Evidence before inference</h2><p class="lp-muted">Keep source excerpts, proposed relationships and instructor confirmation visible in the existing workspace inspector.</p></section></div></section>`}
const stats=rows=>`<div class="lp-stats">${rows.map(([label,value,sub])=>`<div class="lp-stat"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`).join('')}</div>`;
function analytics(){return `<section class="lp-view">${pageHead('Student Analytics','Understand where students need support and inspect the supporting evidence.',tag('Synthetic class data','pending'))}<div class="filter-tabs"><button class="filter-tabs__tab ${analyticsMode==='first'?'filter-tabs__tab--active':''}" data-mode="first">First-pass performance</button><button class="filter-tabs__tab ${analyticsMode==='review'?'filter-tabs__tab--active':''}" data-mode="review">Review evidence · New</button></div><p class="lp-muted">Topic Practice · Capital Budgeting · Path R1 · Last 14 days · Exact question versions</p>${stats(analyticsMode==='first'?[['Students participating','42','One first attempt per student and version'],['Two-year NPV: incorrect','18 / 40','45% · Q043 / v3'],['“Discount once” selected','12 / 40','30% · possible misconception only'],['Skills to investigate','1','Check question quality and diagnostic evidence']]:[['Entered focused review','18','After an incorrect main answer'],['Completed a fresh check','15 / 18','3 students have not completed it'],['Passed the fresh check','11 / 15','73% · not a causal learning claim'],['Delayed check','—','No evidence yet of long-term retention']])}<div class="lp-two"><section class="lp-panel"><h2>${analyticsMode==='first'?'First-pass error signals':'Review participation and outcomes'}</h2>${analyticsMode==='first'?`<div class="lp-bar-row"><span>S01 · Explain NPV</span><div><span style="width:19%"></span></div><strong>19%</strong></div><div class="lp-bar-row"><span>S02 · Multi-period discounting</span><div><span style="width:45%"></span></div><strong>45%</strong></div><div class="lp-bar-row"><span>S03 · Initial investment</span><div><span style="width:25%"></span></div><strong>25%</strong></div><table class="lp-table lp-section"><thead><tr><th>Evidence question</th><th>Incorrect / students</th><th>Interpretation</th></tr></thead><tbody><tr><td>Q041 / v2</td><td>8 / 42</td><td>NPV meaning</td></tr><tr><td>Q043 / v3</td><td>18 / 40</td><td>Multi-skill item; investigate attribution</td></tr><tr><td>Q042 / v1</td><td>10 / 40</td><td>Discounting + initial investment</td></tr></tbody></table><p class="lp-muted">Rates describe linked question evidence, not a definitive skill diagnosis. Suppress results below 5 distinct students.</p>`:[['Entered review','18'],['Completed diagnosis','17 / 18'],['Diagnosis supports period confusion','9 / 17'],['Completed independent check','15 / 18'],['Passed independent check','11 / 15'],['Delayed check','Not available']].map(([l,v])=>`<div class="lp-question-row"><span>${l}</span><strong>${v}</strong></div>`).join('')}</section><aside class="lp-panel"><h2>Revisit the cash-flow timeline</h2><p class="lp-muted">12 of 40 students selected the “discount once” option on Q043. Later diagnostics support period confusion for 9 of 17 students who completed diagnosis.</p><div class="lp-note lp-note--warning lp-section">This is a teaching signal. Check wording, answer rules and course coverage before attributing errors to students.</div><p class="lp-muted lp-section">Try a two-step timeline example in class, then use a different-context question in a later session to check retention.</p><div class="lp-inline lp-section">${btn('Inspect question evidence','evidence',true)}${btn('Edit review branches','to-graph')}</div></aside></div><div class="lp-note lp-section">These sample class metrics are independent of the Student Preview demo. In production, preview attempts remain isolated from student analytics.</div></section>`}
function student(){const s=state.student,q=questions[s.order[s.index]],misses=s.answers.map((answer,i)=>answer!==questions[s.order[i]].correct?s.order[i]:-1).filter(id=>id>=0);let content='';
function options(r){return `<div class="practice-card__options">${r.options.map((o,i)=>`<button class="option-btn ${s.choice===i?'option-btn--selected':''} ${s.submitted&&i===r.correct?'option-btn--correct':''}" data-choice="${i}" ${s.submitted?'disabled':''}><span class="option-btn__key">${'ABCD'[i]}</span><span>${o}</span></button>`).join('')}</div>`}
if(s.phase==='main')content=`<div class="lp-between"><p class="practice-card__qlabel lp-muted">Main question ${s.index+1} of 3</p>${tag(q.skill,'blue')}</div><div class="practice-card__stem">${q.stem}</div>${options(q)}${s.submitted?`<div class="lp-note ${s.choice===q.correct?'lp-note--success':'lp-note--warning'}"><b>${s.choice===q.correct?'Correct':'Added to your review list'}</b><br>${q.explain}${s.choice!==q.correct?'<br>Continue the main questions. We’ll review this together afterward.':''}</div>`:''}<div class="practice-card__footer"><p>Your main sequence stays at 3 questions.<br>Review questions do not interrupt it.</p>${s.submitted?btn(s.index===2?'View summary →':'Next main question →','student-next',true):btn('Submit answer','student-submit',true,s.choice===null)}</div>`;
else if(s.phase==='summary')content=`<h2 style="font-size:22px">Main questions complete</h2><p class="lp-muted">Completed 3 of 3 · ${3-misses.length} correct on the first pass · ${misses.length} for review.</p>${s.order.map((id,i)=>`<div class="lp-question-row"><strong>${i+1}. ${questions[id].title}</strong>${tag(misses.includes(id)?'To review':'Correct first time',misses.includes(id)?'pending':'')}</div>`).join('')}<div class="lp-note lp-section">${misses.includes(2)?'Start with multi-period discounting. A diagnostic, guided practice if needed, and a fresh check take at most 3 answers.':'This demo includes one complete branch for multi-period discounting. Other mistakes keep their original explanation and a review reminder until matching content is available.'}</div><div class="lp-inline lp-section">${btn(misses.includes(2)?'Start focused review →':'Explore the sample review branch →','student-review',true)}${btn('Finish for now','student-finish')}</div>`;
else if(s.phase==='review'){const isDiag=s.reviewIndex===0,isHelp=s.reviewIndex===1&&s.reviewAnswers[0]!==1;const r=isDiag?{stem:'How many periods must a cash flow at the end of year 2 be discounted to reach today?',options:['1 period','2 periods','No discounting'],correct:1,exp:'From year 2 to today spans two periods. Use (1+r)².'}:isHelp?{stem:'A year-2 cash flow of $1,210 is worth $1,100 at the end of year 1, at 10%. What is it worth today?',options:['$1,000','$1,100','$1,210'],correct:0,exp:'Divide by 1.10 once more: $1,100 / 1.10 = $1,000. Each step back one year requires another discount.'}:{stem:'Try new numbers: invest $15,000 today and receive $5,000 at the end of year 2. At 20%, what is the NPV?',options:['−$10,000','−$10,833.33','−$11,527.78'],correct:2,exp:'$5,000 / 1.20² − $15,000 = −$11,527.78.'};content=`<div class="lp-between"><p class="lp-muted">Focused review · ${s.reviewIndex+1} of at most 3</p>${tag(isDiag?'Check understanding':isHelp?'Guided practice':'Independent check','blue')}</div><p class="lp-muted">Why this question? Your two-year NPV answer suggests that discount periods deserve another look. ${isDiag?'Let’s check the timeline first.':isHelp?'Work through one period at a time.':'Apply the same structure with different numbers.'}</p><div class="practice-card__stem">${r.stem}</div>${options(r)}${s.submitted?`<div class="lp-note ${s.choice===r.correct?'lp-note--success':'lp-note--warning'}"><b>${s.choice===r.correct?'This step is correct':'Let’s look at this step'}</b><br>${r.exp}</div>`:''}<div class="practice-card__footer"><p>One bounded review sequence.<br>You can finish without an endless chain of questions.</p>${s.submitted?btn(!isDiag&&!isHelp?'Complete review →':'Continue review →','review-next',true):btn('Submit answer','review-submit',true,s.choice===null)}</div>`}
else{const verified=s.reviewAnswers.length&&s.reviewAnswers.at(-1)===2;content=`<h2 style="font-size:22px">Your progress is saved</h2><p class="lp-muted">Main questions: ${s.answers.length} / 3 · Review answers: ${s.reviewAnswers.length}</p><div class="lp-three"><div class="lp-panel"><h2>First pass</h2><strong style="font-size:27px">${s.answers.filter((a,i)=>a===questions[s.order[i]].correct).length} / ${s.answers.length}</strong><p class="lp-muted">Original performance is preserved.</p></div><div class="lp-panel" style="grid-column:span 2"><h2>${verified?'Fresh check passed':s.reviewAnswers.length?'More practice would help':'Review saved for later'}</h2><p class="lp-muted">${verified?'This is evidence from one independent check. A later question can check retention and transfer.':'Your explanations and remaining review items stay available. This session ends here.'}</p></div></div><div class="lp-inline lp-section">${btn('Start again','restart-student',true)}${btn('See instructor insights →','to-analytics')}</div>`}
return `<section class="lp-view lp-student">${pageHead('Capital Budgeting','Topic Practice · Main questions, then focused review.',btn('Restart preview','restart-student'))}<div class="lp-journey"><span class="${s.phase==='main'?'is-current':''}">1 · Main questions</span><i></i><span class="${['summary','review'].includes(s.phase)?'is-current':''}">2 · Focused review</span><i></i><span class="${s.phase==='done'?'is-current':''}">3 · Summary</span></div><div class="practice-card">${content}</div><p class="lp-muted lp-section">Prototype tip: choose B on “Two-year NPV” to explore the review branch. Your demo progress survives a refresh. No real student records are created.</p></section>`}
function render(){const aliases={};let page=location.hash.slice(1)||'overview';page=aliases[page]||page;shell(page);app.innerHTML=({overview,batch,graph,variants,generation,review,bank,publish,coverage,analytics,student}[page]||overview)();save()}
async function analyze(){if(busy)return;go('graph');busy=true;for(let i=1;i<=3;i++){analysisStage=i;render();await new Promise(r=>setTimeout(r,600))}state.analyzed=true;busy=false;analysisStage=0;render();toast('Analysis ready. Inspect the evidence and confirm the proposed plan.')}
async function generate(fail=false){if(busy||!state.confirmed)return;busy=true;for(let i=1;i<=4;i++){genStage=i;render();await new Promise(r=>setTimeout(r,450))}state.generated=true;state.failed=fail&&state.extra;busy=false;render();toast(state.failed?'Transfer needs source evidence. Other drafts have been preserved.':'Drafts saved. Review each item before publication.')}
function dialog(title,html){document.getElementById('detail-body').innerHTML=`<h2>${title}</h2>${html}`;document.getElementById('detail').showModal()}
document.querySelector('.lp-close').onclick=()=>document.getElementById('detail').close();
document.getElementById('reset').onclick=()=>{if(busy){toast('Wait for the current simulated run to finish.');return}state=initial();render();toast('Demo reset. No production data was accessed.')};
document.getElementById('collapse').onclick=()=>{const sh=document.getElementById('shell'),collapsed=sh.classList.toggle('is-collapsed');document.getElementById('collapse').textContent=collapsed?'›':'‹';document.getElementById('collapse').setAttribute('aria-label',collapsed?'Expand navigation':'Collapse navigation');document.getElementById('collapse').setAttribute('aria-expanded',String(!collapsed))};
document.getElementById('menu').onclick=()=>document.getElementById('shell').classList.toggle('is-open');document.getElementById('backdrop').onclick=()=>document.getElementById('shell').classList.remove('is-open');
document.getElementById('theme').onclick=()=>{const dark=document.documentElement.dataset.theme==='dark';document.documentElement.dataset.theme=dark?'light':'dark';document.getElementById('theme').textContent=dark?'☾':'☀'};
document.addEventListener('click',e=>{const un=e.target.closest('[data-unavailable]');if(un){e.preventDefault();toast('Existing navigation retained. This feature is outside the prototype.')}const sh=e.target.closest('[data-shell]');if(sh)dialog('Prototype only',`<p>The existing ${sh.dataset.shell==='logout'?'sign-out':sh.dataset.shell} control is retained for UI continuity. It is not connected to your account in this prototype.</p>`)});
app.addEventListener('change',e=>{if(e.target.id==='extra'){state.extra=e.target.checked;state.confirmed=false;render()}});
app.addEventListener('input',e=>{if(e.target.id==='minN'){state.minN=Math.max(1,Math.min(2,Math.round(Number(e.target.value)||1)));state.approved=state.approved.filter(x=>x!=='parameters');render();toast('Constraint changed. The parameter pack requires a fresh approval.')}});
app.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el||el.disabled)return;if(el.dataset.route){go(el.dataset.route);return}if(el.dataset.node){selectedNode=el.dataset.node;render();return}if(el.dataset.review){state.selectedReview=el.dataset.review;render();return}if(el.dataset.mode){analyticsMode=el.dataset.mode;render();return}if(el.dataset.up!==undefined){const i=Number(el.dataset.up);if(i>0){[state.order[i-1],state.order[i]]=[state.order[i],state.order[i-1]];toast('Draft order updated. Restart Student Preview to use the new order.')}render();return}if(el.dataset.choice!==undefined){state.student.choice=Number(el.dataset.choice);render();return}const a=el.dataset.action,s=state.student;
if(a?.startsWith('to-')){go(a.slice(3));return}if(a==='analyze'){await analyze();return}if(a==='confirm'){if(!state.analyzed)return;state.confirmed=true;save();go('variants');toast('Plan confirmed. Configure the parameter pack next.');return}if(a==='seed')state.seed++;
if(a==='generate'||a==='generate-failure'){await generate(a==='generate-failure');return}if(a==='retry-generation'){state.failed=false;toast('Sample source fix applied. Only the failed branch was retried; approvals were preserved.')}
if(a==='approve'&&state.generated&&!state.approved.includes(state.selectedReview)){state.approved.push(state.selectedReview);toast('This content version is approved. Publication remains a separate step.')}
if(a==='publish'&&ready()){state.published=true;state.rolledBack=false;toast('Revision 1 published in the demo. Only new sessions use this plan.')}
if(a==='rollback'){state.published=false;state.rolledBack=true;toast('New sessions restored to the previous mode. Existing attempts remain intact.')}
if(a==='restart-student')state.student=freshStudent(state.order);
if(a==='student-submit'){s.submitted=true;s.answers[s.index]=s.choice}
if(a==='student-next'){if(s.index===2)s.phase='summary';else s.index++;s.choice=null;s.submitted=false}
if(a==='student-review'){s.phase='review';s.reviewIndex=0;s.reviewAnswers=[];s.choice=null;s.submitted=false}
if(a==='review-submit'){s.submitted=true;s.reviewAnswers[s.reviewIndex]=s.choice}
if(a==='review-next'){const diag=s.reviewIndex===0,help=s.reviewIndex===1&&s.reviewAnswers[0]!==1;if(!diag&&!help)s.phase='done';else s.reviewIndex++;s.choice=null;s.submitted=false}
if(a==='student-finish')s.phase='done';
if(a==='evidence'){dialog('Q043 / v3 · First-pass evidence',`<p>40 distinct students · 18 incorrect · 45% first-pass error rate. Synthetic data only.</p><table class="lp-table"><tr><th>Option</th><th>Students</th><th>Interpretation</th></tr><tr><td>A · −$8,875</td><td>22</td><td>Correct</td></tr><tr><td>B · −$8,250</td><td>12</td><td>May have discounted only once</td></tr><tr><td>C / D · Other errors</td><td>6 combined</td><td>Small subgroups are not exposed separately</td></tr></table><p>Subsequent diagnosis supports period confusion for 9 of 17 participants. This is a different denominator and does not prove a particular misconception in every student who selected B.</p>`);return}
if(a==='approved-bank'){dialog('Existing approved question bank',`<p>The existing approved collection stays available. “Learning sequence” adds ordering and publication without replacing bank search, filters, editing or version history.</p><table class="lp-table">${questions.map(q=>`<tr><td>${q.id} / ${q.version}</td><td>${q.title}</td><td>${tag('Approved')}</td></tr>`).join('')}</table>`);return}
if(a==='existing-review'||a==='existing-coverage'){dialog('Existing workspace retained','<p>This prototype focuses on the added learning-path view. Existing question review and coverage tools keep their current routes, controls and permissions.</p>');return}
render()});
window.addEventListener('hashchange',()=>{document.getElementById('shell').classList.remove('is-open');render();document.getElementById('view-root').scrollTo({top:0})});render();
